window.archLocalURL = function(url) { const key=url.replace(/\/$/, ''); return (document.documentElement.lang==='en' && window.ARCH_EN_LINKS[key]) || window.ARCH_LINKS[key] || url; };
function archRewriteLinks(root) {
 const links = [...(root.matches && root.matches('a[href]') ? [root] : []), ...(root.querySelectorAll ? root.querySelectorAll('a[href]') : [])];
 links.forEach(a => { const href=a.getAttribute('href'); const local=window.archLocalURL(href); if(a.closest('.source-note,.source-list,.detail-actions,.news-card-bottom') || a.classList.contains('calendar-source'))return; if(local!==href){a.href=local;a.removeAttribute('target');a.removeAttribute('rel');} });
}
document.addEventListener('DOMContentLoaded',()=>{
 archRewriteLinks(document);
 new MutationObserver(records=>records.forEach(r=>r.addedNodes.forEach(n=>{if(n.nodeType===1)archRewriteLinks(n);}))).observe(document.body,{childList:true,subtree:true});
});
